const incoming = $json.body ?? $json;
const nestedPayload = incoming.payload && typeof incoming.payload === 'object' ? incoming.payload : {};
const normalized = {...nestedPayload, ...incoming};
normalized.payload = nestedPayload.payload ?? nestedPayload;
normalized.mode = normalized.mode || 'dry_run';
normalized.action = normalized.action || 'run_lifecycle';
normalized.tool_results = Array.isArray(normalized.tool_results) ? normalized.tool_results : [];
normalized.desired_tools = Array.isArray(normalized.desired_tools) ? normalized.desired_tools : null;
const toolName = 'tool_content_planning';
const shouldRun = !normalized.desired_tools || normalized.desired_tools.includes(toolName);
if (!shouldRun) {
  const results = [...normalized.tool_results, {tool: toolName, status: 'skipped', reason: 'not selected for action'}];
  return [{json: {...normalized, tool_results: results, skipped_tool: toolName}}];
}
return [{json: {...normalized, current_stage: toolName, live_mode: normalized.mode === 'live'}}];

const state = $node['Normalize And Auth'].json;
if (state.skipped_tool) {
  return [{json: state}];
}
const rawText = $json.choices?.[0]?.message?.content ?? $json.body?.choices?.[0]?.message?.content ?? $json.data?.choices?.[0]?.message?.content ?? '';
let parsed;
let parseWarning = false;
let warningMessage = '';
if (state.mode === 'dry_run' && !rawText) {
  parsed = state.fallback_payload || state.content_plan || {mode: 'dry_run', workflow: state.current_stage, note: 'dry-run fallback output'};
} else {
  try {
    parsed = typeof rawText === 'string' ? JSON.parse(rawText) : rawText;
  } catch (error) {
    parseWarning = true;
    warningMessage = error.message;
    parsed = {raw_text: rawText, parse_warning: true};
  }
}
const outputJson = JSON.stringify(parsed || {});
const safeSql = value => String(value ?? '').replace(/'/g, "''");
return [{json: {...state, content_plan: parsed, content_plan_json: outputJson, content_plan_json_sql: safeSql(outputJson), raw_model_text: rawText, raw_model_text_sql: safeSql(rawText), parse_warning: parseWarning, warning_message: warningMessage, warning_message_sql: safeSql(warningMessage), current_stage_sql: safeSql(state.current_stage), output_type_sql: safeSql(state.output_type), dispatch_label_sql: safeSql(state.dispatch_label), qa_status: 'pending'}}];

