INSERT INTO content_errors (job_id, severity, error_code, error_message, recoverable, context)
SELECT NULLIF('{{$json.job_id}}','')::uuid, 'warning', 'CONTENT_PLAN_PARSE_WARNING', COALESCE(NULLIF('{{$json.warning_message_sql}}',''),'LLM response parse warning'), true, jsonb_build_object('raw_text', LEFT('{{$json.raw_model_text_sql}}', 2000), 'workflow', '{{$json.current_stage_sql}}')
WHERE COALESCE('{{$json.parse_warning}}','false') = 'true';

INSERT INTO content_outputs (job_id, output_type, title, structured_data, qa_status)
VALUES (NULLIF('{{$json.job_id}}','')::uuid, 'content_plan', 'Content plan', COALESCE(NULLIF('{{$json.content_plan_json_sql}}',''),'{}')::jsonb, 'pending');
UPDATE content_jobs SET status='waiting_for_plan_approval', updated_at=now() WHERE id=NULLIF('{{$json.job_id}}','')::uuid;
INSERT INTO content_events (job_id,event_type,message,metadata) VALUES (NULLIF('{{$json.job_id}}','')::uuid,'approval_gate','Content plan approval gate reached',jsonb_build_object('approval_stage','plan'));
SELECT NULLIF('{{$json.job_id}}','') AS job_id, 'waiting_for_plan_approval' AS status;

